[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --navy: #1B1464;
      --navy-light: #2a2080;
      --yellow: #FFD930;
      --yellow-hover: #f5cc1a;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --blue: #3B82F6;
      --blue-light: #EFF6FF;
      --teal: #0D9488;
      --teal-light: #CCFBF1;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.05);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--gray-800);
      line-height: 1.6;
      background: var(--white);
      -webkit-font-smoothing: antialiased;
    }

    /* ========== HEADER ========== */
    .header {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow 0.3s;
    }
    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      font-weight: 800;
      font-size: 24px;
      color: var(--navy);
    }
    .logo-icon {
      width: 36px; height: 36px;
      background: var(--navy);
      border-radius: var(--radius-sm);
      display: flex; align-items: center; justify-content: center;
    }
    .logo-icon svg { width: 20px; height: 20px; }
    .logo span { color: var(--yellow); }

    .nav-desktop { display: flex; align-items: center; gap: 32px; }
    .nav-links { display: flex; gap: 8px; }
    .nav-links a {
      text-decoration: none;
      color: var(--gray-600);
      font-size: 15px;
      font-weight: 500;
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      transition: color 0.2s, background 0.2s;
    }
    .nav-links a:hover { color: var(--navy); background: var(--gray-50); }

    .nav-actions { display: flex; align-items: center; gap: 12px; }
    .btn-text {
      background: none; border: none; cursor: pointer;
      font-family: inherit; font-size: 15px; font-weight: 500;
      color: var(--navy); padding: 8px 16px;
      border-radius: var(--radius-sm);
      transition: background 0.2s;
    }
    .btn-text:hover { background: var(--gray-50); }

    .btn-primary {
      display: inline-flex; align-items: center; justify-content: center;
      background: var(--navy); color: var(--white);
      border: none; border-radius: var(--radius-sm);
      padding: 10px 24px; font-family: inherit;
      font-size: 15px; font-weight: 600;
      cursor: pointer; transition: background 0.2s, transform 0.1s;
    }
    .btn-primary:hover { background: var(--navy-light); }
    .btn-primary:active { transform: scale(0.97); }

    .btn-yellow {
      display: inline-flex; align-items: center; justify-content: center;
      background: var(--yellow); color: var(--navy);
      border: none; border-radius: var(--radius-sm);
      padding: 10px 24px; font-family: inherit;
      font-size: 15px; font-weight: 600;
      cursor: pointer; transition: background 0.2s, transform 0.1s;
    }
    .btn-yellow:hover { background: var(--yellow-hover); }
    .btn-yellow:active { transform: scale(0.97); }

    .hamburger {
      display: none;
      background: none; border: none; cursor: pointer;
      width: 44px; height: 44px; align-items: center; justify-content: center;
      border-radius: var(--radius-sm);
    }
    .hamburger:hover { background: var(--gray-50); }
    .hamburger svg { width: 24px; height: 24px; color: var(--navy); }

    /* Mobile drawer */
    .mobile-overlay {
      display: none; position: fixed; inset: 0;
      background: rgba(0,0,0,0.4); z-index: 1001;
      opacity: 0; transition: opacity 0.3s;
    }
    .mobile-overlay.active { display: block; opacity: 1; }

    .mobile-drawer {
      position: fixed; top: 0; right: -320px;
      width: 300px; max-width: 85vw; height: 100vh;
      background: var(--white); z-index: 1002;
      transition: right 0.3s ease;
      padding: 24px;
      box-shadow: var(--shadow-xl);
    }
    .mobile-drawer.active { right: 0; }

    .drawer-close {
      background: none; border: none; cursor: pointer;
      width: 44px; height: 44px; display: flex; align-items: center; justify-content: center;
      border-radius: var(--radius-sm);
      margin-left: auto;
    }
    .drawer-close:hover { background: var(--gray-50); }
    .drawer-close svg { width: 24px; height: 24px; color: var(--gray-600); }

    .drawer-nav { margin-top: 32px; display: flex; flex-direction: column; gap: 4px; }
    .drawer-nav a {
      text-decoration: none; color: var(--gray-700);
      font-size: 18px; font-weight: 500;
      padding: 14px 16px; border-radius: var(--radius-sm);
      transition: background 0.2s;
    }
    .drawer-nav a:hover { background: var(--gray-50); }

    .drawer-actions {
      margin-top: 24px; display: flex; flex-direction: column; gap: 12px;
      padding-top: 24px; border-top: 1px solid var(--gray-200);
    }
    .drawer-actions .btn-primary,
    .drawer-actions .btn-yellow { width: 100%; text-align: center; padding: 14px; }

    /* ========== HERO ========== */
    .hero {
      padding: 140px 24px 80px;
      background: linear-gradient(165deg, var(--navy) 0%, #1e1880 40%, #2520a0 100%);
      position: relative; overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute; top: -50%; right: -20%;
      width: 800px; height: 800px;
      background: radial-gradient(circle, rgba(255,217,48,0.08) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute; bottom: -30%; left: -10%;
      width: 600px; height: 600px;
      background: radial-gradient(circle, rgba(59,130,246,0.08) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 1200px; margin: 0 auto;
      text-align: center; position: relative; z-index: 1;
    }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 100px; padding: 8px 20px;
      margin-bottom: 32px;
      color: rgba(255,255,255,0.9); font-size: 14px; font-weight: 500;
    }
    .hero-badge-dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: #34D399; animation: pulse 2s infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.5; }
    }

    .hero h1 {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 800; color: var(--white);
      line-height: 1.1; margin-bottom: 20px;
      letter-spacing: -0.02em;
    }
    .hero h1 .highlight {
      background: linear-gradient(90deg, var(--yellow), #ffe066);
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero p {
      font-size: clamp(16px, 2vw, 20px);
      color: rgba(255,255,255,0.75);
      max-width: 640px; margin: 0 auto 48px;
      line-height: 1.6;
    }

    /* ========== SEARCH BAR ========== */
    .search-container {
      max-width: 880px; margin: 0 auto;
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 8px;
      box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
      position: relative;
    }
    .search-form {
      display: flex; align-items: center; gap: 4px;
    }
    .search-field {
      flex: 1; position: relative;
      display: flex; align-items: center; gap: 10px;
      padding: 14px 16px;
      border-radius: var(--radius-md);
      transition: background 0.2s;
    }
    .search-field:focus-within { background: var(--gray-50); }
    .search-field + .search-field { border-left: 1px solid var(--gray-200); }

    .search-field svg { width: 20px; height: 20px; color: var(--gray-400); flex-shrink: 0; }

    .search-field input,
    .search-field select {
      border: none; background: none; outline: none;
      font-family: inherit; font-size: 15px;
      color: var(--gray-800); width: 100%;
    }
    .search-field input::placeholder { color: var(--gray-400); }
    .search-field select { cursor: pointer; -webkit-appearance: none; appearance: none; }

    .search-btn {
      background: var(--navy); color: var(--white);
      border: none; border-radius: var(--radius-md);
      padding: 16px 32px; font-family: inherit;
      font-size: 16px; font-weight: 600;
      cursor: pointer; white-space: nowrap;
      transition: background 0.2s, transform 0.1s;
      display: flex; align-items: center; gap: 8px;
    }
    .search-btn:hover { background: var(--navy-light); }
    .search-btn:active { transform: scale(0.97); }
    .search-btn svg { width: 18px; height: 18px; }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 4px); left: 0; right: 0;
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-xl);
      border: 1px solid var(--gray-200);
      max-height: 320px; overflow-y: auto;
      z-index: 10; display: none;
    }
    .autocomplete-dropdown.active { display: block; }
    .autocomplete-item {
      display: flex; align-items: center; gap: 12px;
      padding: 12px 20px;
      cursor: pointer; transition: background 0.15s;
      font-size: 15px; color: var(--gray-700);
    }
    .autocomplete-item:hover { background: var(--gray-50); }
    .autocomplete-item:first-child { border-radius: var(--radius-md) var(--radius-md) 0 0; }
    .autocomplete-item:last-child { border-radius: 0 0 var(--radius-md) var(--radius-md); }
    .autocomplete-item svg { width: 18px; height: 18px; color: var(--gray-400); flex-shrink: 0; }
    .autocomplete-item .type { margin-left: auto; font-size: 12px; color: var(--gray-400); text-transform: uppercase; letter-spacing: 0.05em; }

    /* ========== STATS ========== */
    .stats {
      padding: 64px 24px;
      background: var(--gray-50);
      border-bottom: 1px solid var(--gray-200);
    }
    .stats-inner {
      max-width: 1200px; margin: 0 auto;
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
    }
    .stat-item { text-align: center; }
    .stat-value {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 800; color: var(--navy);
      line-height: 1.1; margin-bottom: 4px;
    }
    .stat-value .accent { color: var(--teal); }
    .stat-label {
      font-size: 15px; color: var(--gray-500); font-weight: 500;
    }

    /* ========== SPECIALTIES ========== */
    .specialties {
      padding: 96px 24px;
      background: var(--white);
    }
    .section-inner {
      max-width: 1200px; margin: 0 auto;
    }
    .section-header {
      text-align: center; margin-bottom: 56px;
    }
    .section-label {
      display: inline-block;
      font-size: 13px; font-weight: 600;
      color: var(--teal); text-transform: uppercase;
      letter-spacing: 0.08em; margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800; color: var(--navy);
      line-height: 1.15; letter-spacing: -0.02em;
      margin-bottom: 16px;
    }
    .section-desc {
      font-size: 17px; color: var(--gray-500);
      max-width: 520px; margin: 0 auto;
    }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .specialty-card {
      display: flex; align-items: center; gap: 16px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      padding: 24px;
      cursor: pointer;
      transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
      text-decoration: none; color: inherit;
    }
    .specialty-card:hover {
      border-color: var(--navy);
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }
    .specialty-icon {
      width: 56px; height: 56px;
      border-radius: var(--radius-md);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .specialty-icon svg { width: 28px; height: 28px; }
    .specialty-info h3 {
      font-size: 17px; font-weight: 700;
      color: var(--navy); margin-bottom: 2px;
    }
    .specialty-info p {
      font-size: 14px; color: var(--gray-500);
      line-height: 1.4;
    }

    .specialty-card:nth-child(1) .specialty-icon { background: #EFF6FF; color: #3B82F6; }
    .specialty-card:nth-child(2) .specialty-icon { background: #FEF3C7; color: #D97706; }
    .specialty-card:nth-child(3) .specialty-icon { background: #FCE7F3; color: #DB2777; }
    .specialty-card:nth-child(4) .specialty-icon { background: #EDE9FE; color: #7C3AED; }
    .specialty-card:nth-child(5) .specialty-icon { background: #CCFBF1; color: #0D9488; }
    .specialty-card:nth-child(6) .specialty-icon { background: #FEE2E2; color: #DC2626; }

    /* ========== HOW IT WORKS ========== */
    .how-it-works {
      padding: 96px 24px;
      background: var(--gray-50);
    }
    .steps-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
      position: relative;
    }
    .step {
      text-align: center; position: relative;
    }
    .step-number {
      width: 64px; height: 64px;
      border-radius: 50%;
      background: var(--navy);
      color: var(--yellow);
      font-size: 24px; font-weight: 800;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 24px;
      position: relative; z-index: 1;
    }
    .step-icon {
      width: 80px; height: 80px;
      border-radius: var(--radius-lg);
      background: var(--white);
      box-shadow: var(--shadow-md);
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 20px;
    }
    .step-icon svg { width: 36px; height: 36px; color: var(--navy); }
    .step h3 {
      font-size: 20px; font-weight: 700;
      color: var(--navy); margin-bottom: 10px;
    }
    .step p {
      font-size: 15px; color: var(--gray-500);
      line-height: 1.6; max-width: 300px; margin: 0 auto;
    }

    /* Connector lines between steps */
    .steps-grid::before {
      content: '';
      position: absolute;
      top: 40px;
      left: calc(16.66% + 32px);
      right: calc(16.66% + 32px);
      height: 2px;
      background: linear-gradient(90deg, var(--navy), var(--yellow), var(--navy));
      opacity: 0.2;
    }

    /* ========== TESTIMONIALS ========== */
    .testimonials {
      padding: 96px 24px;
      background: var(--white);
    }
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .testimonial-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px;
      transition: box-shadow 0.2s;
    }
    .testimonial-card:hover { box-shadow: var(--shadow-lg); }
    .testimonial-stars {
      display: flex; gap: 2px; margin-bottom: 16px;
    }
    .testimonial-stars svg { width: 18px; height: 18px; color: var(--yellow); fill: var(--yellow); }
    .testimonial-card blockquote {
      font-size: 16px; color: var(--gray-700);
      line-height: 1.7; margin-bottom: 24px;
      font-style: italic;
    }
    .testimonial-author {
      display: flex; align-items: center; gap: 12px;
    }
    .testimonial-avatar {
      width: 44px; height: 44px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; font-size: 16px; color: var(--white);
    }
    .testimonial-card:nth-child(1) .testimonial-avatar { background: #3B82F6; }
    .testimonial-card:nth-child(2) .testimonial-avatar { background: #7C3AED; }
    .testimonial-card:nth-child(3) .testimonial-avatar { background: #0D9488; }
    .testimonial-name {
      font-size: 15px; font-weight: 600; color: var(--navy);
    }
    .testimonial-location {
      font-size: 13px; color: var(--gray-400);
    }

    /* ========== APP PROMO ========== */
    .app-promo {
      padding: 96px 24px;
      background: linear-gradient(165deg, var(--navy) 0%, #1e1880 40%, #2520a0 100%);
      position: relative; overflow: hidden;
    }
    .app-promo::before {
      content: '';
      position: absolute; top: -50%; right: -20%;
      width: 800px; height: 800px;
      background: radial-gradient(circle, rgba(255,217,48,0.06) 0%, transparent 70%);
      pointer-events: none;
    }
    .app-promo-inner {
      max-width: 1200px; margin: 0 auto;
      display: flex; align-items: center; gap: 80px;
      position: relative; z-index: 1;
    }
    .app-content { flex: 1; }
    .app-content .section-label { color: var(--yellow); }
    .app-content .section-title { color: var(--white); }
    .app-content .section-desc { color: rgba(255,255,255,0.7); }

    .app-features {
      list-style: none;
      margin: 32px 0 40px;
      display: flex; flex-direction: column; gap: 16px;
    }
    .app-features li {
      display: flex; align-items: center; gap: 12px;
      color: rgba(255,255,255,0.85);
      font-size: 16px;
    }
    .app-features li svg { width: 20px; height: 20px; color: var(--yellow); flex-shrink: 0; }

    .app-buttons {
      display: flex; gap: 16px; flex-wrap: wrap;
    }
    .app-btn {
      display: inline-flex; align-items: center; gap: 12px;
      background: var(--white); color: var(--navy);
      border: none; border-radius: var(--radius-md);
      padding: 14px 24px; font-family: inherit;
      cursor: pointer; transition: transform 0.15s, box-shadow 0.2s;
      text-decoration: none;
    }
    .app-btn:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
    .app-btn svg { width: 28px; height: 28px; }
    .app-btn-text { text-align: left; }
    .app-btn-small { font-size: 11px; color: var(--gray-500); display: block; }
    .app-btn-big { font-size: 16px; font-weight: 700; display: block; line-height: 1.2; }

    .app-phone {
      flex-shrink: 0;
      width: 280px; height: 480px;
      background: rgba(255,255,255,0.08);
      border-radius: 40px;
      border: 3px solid rgba(255,255,255,0.15);
      display: flex; align-items: center; justify-content: center;
      position: relative; overflow: hidden;
    }
    .phone-screen {
      width: 240px; height: 400px;
      background: var(--white);
      border-radius: 28px;
      overflow: hidden;
      display: flex; flex-direction: column; align-items: center;
      padding: 24px 16px;
    }
    .phone-header {
      width: 100%; text-align: center;
      margin-bottom: 20px;
    }
    .phone-header .mini-logo {
      font-size: 14px; font-weight: 800; color: var(--navy);
    }
    .phone-header .mini-logo span { color: var(--yellow); }
    .phone-search {
      width: 100%; height: 40px;
      background: var(--gray-50);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-sm);
      display: flex; align-items: center; padding: 0 12px;
      gap: 8px; font-size: 12px; color: var(--gray-400);
    }
    .phone-search svg { width: 14px; height: 14px; }
    .phone-cards {
      width: 100%; display: flex; flex-direction: column; gap: 10px;
      margin-top: 16px;
    }
    .phone-card {
      background: var(--gray-50);
      border-radius: var(--radius-sm);
      padding: 10px 12px;
      display: flex; align-items: center; gap: 10px;
    }
    .phone-card-avatar {
      width: 32px; height: 32px; border-radius: 50%;
      background: var(--navy); flex-shrink: 0;
    }
    .phone-card-info { font-size: 11px; }
    .phone-card-name { font-weight: 600; color: var(--navy); }
    .phone-card-detail { color: var(--gray-400); margin-top: 2px; }

    /* ========== FOOTER ========== */
    .footer {
      background: var(--gray-800);
      padding: 64px 24px 32px;
    }
    .footer-inner {
      max-width: 1200px; margin: 0 auto;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }
    .footer-brand .logo {
      color: var(--white); margin-bottom: 16px;
    }
