  <script>
    // ===== HEADER SCROLL EFFECT =====
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    });

    // ===== MOBILE MENU =====
    const hamburger = document.getElementById('hamburger-btn');
    const drawer = document.getElementById('mobile-drawer');
    const overlay = document.getElementById('mobile-overlay');
    const closeBtn = document.getElementById('drawer-close');

    function openDrawer() {
      drawer.classList.add('active');
      overlay.classList.add('active');
      document.body.style.overflow = 'hidden';
    }
    function closeDrawer() {
      drawer.classList.remove('active');
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    }

    hamburger.addEventListener('click', openDrawer);
    closeBtn.addEventListener('click', closeDrawer);
    overlay.addEventListener('click', closeDrawer);

    document.querySelectorAll('.drawer-link').forEach(link => {
      link.addEventListener('click', () => {
        closeDrawer();
      });
    });

    // ===== AUTOCOMPLETE SEARCH =====
    const searchInput = document.getElementById('search-input');
    const dropdown = document.getElementById('autocomplete-dropdown');

    const suggestions = [
      { text: 'Dentist', type: 'Specialty' },
      { text: 'Dermatologist', type: 'Specialty' },
      { text: 'Primary Care Doctor', type: 'Specialty' },
      { text: 'Psychiatrist', type: 'Specialty' },
      { text: 'Eye Doctor', type: 'Specialty' },
      { text: 'Orthopedic Surgeon', type: 'Specialty' },
      { text: 'Back Pain', type: 'Condition' },
      { text: 'Skin Rash', type: 'Condition' },
      { text: 'Anxiety', type: 'Condition' },
      { text: 'Headache', type: 'Condition' },
      { text: 'Toothache', type: 'Condition' },
      { text: 'Dr. Sarah Chen', type: 'Doctor' },
      { text: 'Dr. Michael Ross', type: 'Doctor' },
      { text: 'Dr. Lisa Park', type: 'Doctor' },
    ];

    searchInput.addEventListener('input', function() {
      const val = this.value.trim().toLowerCase();
      if (val.length === 0) {
        dropdown.classList.remove('active');
        return;
      }
      const matches = suggestions.filter(s =>
        s.text.toLowerCase().includes(val)
      ).slice(0, 6);

      if (matches.length === 0) {
        dropdown.classList.remove('active');
        return;
      }

      dropdown.innerHTML = matches.map(m => `
        <div class="autocomplete-item" role="option" data-value="${m.text}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
            <circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
          </svg>
          <span>${m.text}</span>
          <span class="type">${m.type}</span>
        </div>
      `).join('');

      dropdown.classList.add('active');

      dropdown.querySelectorAll('.autocomplete-item').forEach(item => {
        item.addEventListener('click', function() {
          searchInput.value = this.dataset.value;
          dropdown.classList.remove('active');
        });
      });
    });

    document.addEventListener('click', function(e) {
      if (!e.target.closest('#search-container')) {
        dropdown.classList.remove('active');
      }
    });

    // ===== SEARCH FORM SUBMIT =====
    document.getElementById('search-form').addEventListener('submit', function(e) {
      e.preventDefault();
      const query = searchInput.value;
      const location = document.getElementById('location-input').value;
      const insurance = document.getElementById('insurance-select').value;
      // In a real app, this would navigate to search results
      alert(`Searching for: ${query || 'All providers'} near ${location || 'anywhere'} with insurance: ${insurance || 'any'}`);
    });

    // ===== SPECIALTY CARD CLICKS =====
    document.querySelectorAll('.specialty-card').forEach(card => {
      card.addEventListener('click', function(e) {
        e.preventDefault();
        const specialty = this.dataset.specialty;
        // Set search input and scroll to hero
        searchInput.value = specialty;
        window.scrollTo({ top: 0, behavior: 'smooth' });
        searchInput.focus();
      });
    });

    // ===== SCROLL ANIMATIONS =====
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -40px 0px' }
    );

    document.querySelectorAll('.fade-up').forEach(el => observer.observe(el));

    // ===== STAGGER ANIMATIONS =====
    document.querySelectorAll('.specialties-grid .fade-up, .testimonials-grid .fade-up, .steps-grid .fade-up, .stats-inner .fade-up').forEach((el, i) => {
      el.style.transitionDelay = `${i * 80}ms`;
    });
  </script>
